import { supabase } from './client'

/**
 * central_users — application-level user, primary key shared with auth.uid().
 * Schema (docs/schema-map.md): id (uuid, no default), email, tenant_id (not null), preferences.
 */
export type CentralUser = {
  id: string
  email: string | null
  tenant_id: string
  preferences: Record<string, unknown>
}

export const centralUsersService = {
  async get(id: string): Promise<CentralUser | null> {
    const { data, error } = await supabase
      .from('central_users')
      .select('id, email, tenant_id, preferences')
      .eq('id', id)
      .maybeSingle()
    if (error) {
      console.warn('[centralUsers] get failed:', error.message)
      return null
    }
    return (data as CentralUser) ?? null
  },

  /**
   * Idempotent. If the row exists, returns it untouched (does NOT overwrite tenant_id).
   * If missing, inserts with id = auth.uid(), email from auth, tenant_id from caller.
   */
  async ensure(input: { authUserId: string; email: string | null; tenantId: string }): Promise<CentralUser | null> {
    const existing = await this.get(input.authUserId)
    if (existing) return existing
    const { data, error } = await supabase
      .from('central_users')
      .insert({
        id: input.authUserId,
        email: input.email,
        tenant_id: input.tenantId,
        preferences: {},
      })
      .select('id, email, tenant_id, preferences')
      .single()
    if (error) {
      console.warn('[centralUsers] ensure insert failed:', error.message)
      return null
    }
    return data as CentralUser
  },
}
